import { slides } from './storyContent.js';
const $=s=>document.querySelector(s);
const deck=$('#deck');let current=0,returnFocus;
deck.innerHTML=slides.map((s,i)=>`<section class="slide" id="page-${i+1}" aria-labelledby="title-${i}" hidden><div class="slide-inner"><div class="kicker">${s.chapter}</div><h1 class="title" id="title-${i}">${s.title}</h1><p class="page-question">${s.question}</p>${s.body}<div class="takeaway"><b>本页要点</b><span>${s.takeaway}</span></div><p class="next-context">${s.next}</p></div></section>`).join('');
const pages=[...deck.children];
$('#progress').innerHTML=slides.map((s,i)=>`<button aria-label="第 ${i+1} 页：${s.title}" title="${s.title}" data-page="${i}"></button>`).join('');
$('#overviewGrid').innerHTML=slides.map((s,i)=>`<button class="thumb" data-page="${i}"><b>${String(i+1).padStart(2,'0')} · ${s.chapter}</b><span>${s.title}</span></button>`).join('');
function renderEvidence(){const e=slides[current].evidence;$('#evidenceContent').innerHTML=`<div class="source-meta">${e.page}</div><span class="tag">${e.kind}</span><h3>本页内容与来源的关系</h3><p class="meaning">${e.text}</p><p class="meaning">此处为中文出处说明与转述，非逐字引文。页码按用户提供的论文 PDF 页码标记。</p><a class="paper-link" href="./mental-world-modeling.pdf#page=${(e.page.match(/pp?\.(\d+)/)||[])[1]||1}" target="_blank" rel="noopener">打开论文 PDF ↗</a>`;}
function go(index,updateHash=true){current=Math.max(0,Math.min(slides.length-1,index));pages.forEach((el,i)=>{el.hidden=i!==current;el.classList.toggle('active',i===current);});pages[current].scrollTop=0;[...$('#progress').children].forEach((el,i)=>{el.classList.toggle('active',i===current);el.setAttribute('aria-current',i===current?'page':'false');});$('#counter').textContent=`${String(current+1).padStart(2,'0')} / ${slides.length}`;$('#prevBtn').disabled=current===0;$('#nextBtn').disabled=current===slides.length-1;document.title=`${current+1}. ${slides[current].title} · 心理世界建模`;if(updateHash)history.replaceState(null,'',`#page-${current+1}`);renderEvidence();}
function closePanels(){for(const s of ['.drawer','.overview']){$(s).classList.remove('open');$(s).inert=true;$(s).setAttribute('aria-hidden','true');}$('#scrim').classList.remove('open');for(const s of ['#deck','.chrome','#progress','.reading-controls'])$(s).inert=false;returnFocus?.focus();}
function openPanel(selector,focusSelector){returnFocus=document.activeElement;const panel=$(selector);panel.inert=false;panel.classList.add('open');panel.setAttribute('aria-hidden','false');$('#scrim').classList.add('open');for(const s of ['#deck','.chrome','#progress','.reading-controls'])$(s).inert=true;$(focusSelector).focus();}
$('#evidenceBtn').onclick=()=>openPanel('.drawer','#closeDrawer');$('#menuBtn').onclick=()=>openPanel('.overview','#closeOverview');$('#closeDrawer').onclick=$('#closeOverview').onclick=$('#scrim').onclick=closePanels;$('#prevBtn').onclick=()=>go(current-1);$('#nextBtn').onclick=()=>go(current+1);
for(const selector of ['#progress','#overviewGrid'])$(selector).onclick=e=>{const b=e.target.closest('[data-page]');if(b){closePanels();go(Number(b.dataset.page));}};
$('#fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('#fullscreenBtn').textContent='浏览器未允许全屏';}};
addEventListener('keydown',e=>{const panel=$('.drawer.open,.overview.open');if(e.key==='Escape'){closePanels();return;}if(panel){if(e.key==='Tab'){const f=[...panel.querySelectorAll('a[href],button')],first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.target.closest('button,a,summary,input,textarea,select'))return;if(e.key==='ArrowRight'){e.preventDefault();go(current+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(current-1);}if(e.key.toLowerCase()==='o')openPanel('.overview','#closeOverview');});
addEventListener('hashchange',()=>go((Number(location.hash.match(/page-(\d+)/)?.[1])||1)-1,false));$('.drawer').inert=true;$('.overview').inert=true;go((Number(location.hash.match(/page-(\d+)/)?.[1])||1)-1);
